// Servicos.js
import { Plus, Pencil, Trash2, Check, X } from 'lucide-react';
import React, { useEffect, useState } from 'react';
import api from '../../api/axios';
import './Servicos.css';

export default function Servicos() {
  const [servicos, setServicos] = useState([]);
  const [editandoId, setEditandoId] = useState(null);
  const [dadosEditados, setDadosEditados] = useState({});
  const [perfilUsuario, setPerfilUsuario] = useState(null);

  useEffect(() => {
    async function fetchPerfil() {
      try {
        const { data } = await api.get("/api/me");
        setPerfilUsuario(data.perfil);
      } catch (err) {
        console.error("Erro ao buscar perfil:", err);
      }
    }
    fetchPerfil();
  }, []);

  useEffect(() => {
    carregarServicos();
  }, []);

  const carregarServicos = async () => {
    const res = await api.get('/api/servicos/');
    const dadosFormatados = (res.data.results || res.data).map(s => ({
      ...s,
      tempo_execucao: s.tempo_execucao || '00:00',
    }));
    setServicos(dadosFormatados);
  };

  const editar = (servico) => {
    setEditandoId(servico.id);
    setDadosEditados({ ...servico });
  };

  const cancelar = () => {
    setEditandoId(null);
    setDadosEditados({});
  };

  const salvar = async (id) => {
    const formData = new FormData();
    formData.append("nome", dadosEditados.nome);
    formData.append("prazo_dias", dadosEditados.prazo_dias);
    formData.append("tempo_execucao", dadosEditados.tempo_execucao);

    if (dadosEditados.checklist instanceof File) {
      formData.append("checklist", dadosEditados.checklist);
    }
    if (dadosEditados.instrucao_trabalho instanceof File) {
      formData.append("instrucao_trabalho", dadosEditados.instrucao_trabalho);
    }
    if (dadosEditados.video_explicativo instanceof File) {
      formData.append("video_explicativo", dadosEditados.video_explicativo);
    }
    if (dadosEditados.topico_rapido instanceof File) {
      formData.append("topico_rapido", dadosEditados.topico_rapido);
    }

    await api.put(`/api/servicos/${id}/`, formData, {
      headers: { "Content-Type": "multipart/form-data" },
    });

    cancelar();
    carregarServicos();
  };

  const excluir = async (id) => {
    if (window.confirm('Confirma a exclusão?')) {
      await api.delete(`/api/servicos/${id}/`);
      carregarServicos();
    }
  };

  const novo = async () => {
    const novoServico = { nome: "Novo Serviço", prazo_dias: 0, tempo_execucao: "00:00" };

    const res = await api.post("/api/servicos/", novoServico);
    setEditandoId(res.data.id);
    setDadosEditados(novoServico);
    carregarServicos();
  };

  return (
    <div className="servicos-container">
      <div className="servicos-header">
        <h2>Serviços</h2>
        {(perfilUsuario === "admin" || perfilUsuario === "coordenador") && (
          <button onClick={novo} disabled={editandoId !== null} title="Novo Serviço">
            <Plus size={18} />
          </button>
        )}
      </div>
      <table>
        <thead>
          <tr>
            <th className="col-nome">Nome</th>
            <th className="col-prazo">Prazo (dias)</th>
            <th className="col-tempo">Tempo Execução</th>
            <th>Checklist</th>
            <th>Instrução</th>
            <th>Vídeo</th>
            <th>Tópico Rápido</th>
            <th className="col-acoes">Ações</th>
          </tr>
        </thead>
        <tbody>
          {servicos.map(servico => (
            <tr key={servico.id}>
              <td>
                {editandoId === servico.id ? (
                  <input
                    value={dadosEditados.nome}
                    onChange={(e) => setDadosEditados({ ...dadosEditados, nome: e.target.value })}
                  />
                ) : (
                  servico.nome
                )}
              </td>
              <td>
                {editandoId === servico.id ? (
                  <input
                    type="number"
                    value={dadosEditados.prazo_dias}
                    onChange={(e) => setDadosEditados({ ...dadosEditados, prazo_dias: e.target.value })}
                  />
                ) : (
                  servico.prazo_dias
                )}
              </td>
              <td>
                {editandoId === servico.id ? (
                  <input
                    type="text"
                    value={dadosEditados.tempo_execucao}
                    onChange={(e) => {
                      let valor = e.target.value.replace(/\D/g, "");
                      if (valor.length === 0) {
                        setDadosEditados({ ...dadosEditados, tempo_execucao: "" });
                        return;
                      }
                      if (valor.length <= 2) {
                        setDadosEditados({ ...dadosEditados, tempo_execucao: valor });
                      } else {
                        const horas = valor.slice(0, -2);
                        let minutos = valor.slice(-2);
                        if (parseInt(minutos, 10) > 59) minutos = "59";
                        const formatado = `${parseInt(horas, 10)}:${minutos.padStart(2, "0")}`;
                        setDadosEditados({ ...dadosEditados, tempo_execucao: formatado });
                      }
                    }}
                    placeholder="HH:MM"
                  />
                ) : (
                  servico.tempo_execucao
                )}
              </td>

              {/* Checklist */}
              <td>
                {editandoId === servico.id ? (
                  <>
                    <input
                      type="file"
                      accept="application/pdf"
                      onChange={(e) => setDadosEditados({ ...dadosEditados, checklist: e.target.files[0] })}
                    />
                    {servico.checklist && (
                      <a href={servico.checklist} target="_blank" rel="noreferrer">📎</a>
                    )}
                  </>
                ) : (
                  servico.checklist ? (
                    <a href={servico.checklist} target="_blank" rel="noreferrer">📎</a>
                  ) : "-"
                )}
              </td>

              {/* Instrução */}
              <td>
                {editandoId === servico.id ? (
                  <>
                    <input
                      type="file"
                      accept="application/pdf"
                      onChange={(e) => setDadosEditados({ ...dadosEditados, instrucao_trabalho: e.target.files[0] })}
                    />
                    {servico.instrucao_trabalho && (
                      <a href={servico.instrucao_trabalho} target="_blank" rel="noreferrer">📎</a>
                    )}
                  </>
                ) : (
                  servico.instrucao_trabalho ? (
                    <a href={servico.instrucao_trabalho} target="_blank" rel="noreferrer">📎</a>
                  ) : "-"
                )}
              </td>

              {/* Vídeo */}
              <td>
                {editandoId === servico.id ? (
                  <>
                    <input
                      type="file"
                      accept="video/*"
                      onChange={(e) => setDadosEditados({ ...dadosEditados, video_explicativo: e.target.files[0] })}
                    />
                    {servico.video_explicativo && (
                      <a href={servico.video_explicativo} target="_blank" rel="noreferrer">🎥</a>
                    )}
                  </>
                ) : (
                  servico.video_explicativo ? (
                    <a href={servico.video_explicativo} target="_blank" rel="noreferrer">🎥</a>
                  ) : "-"
                )}
              </td>

              {/* Tópico Rápido */}
              <td>
                {editandoId === servico.id ? (
                  <>
                    <input
                      type="file"
                      accept="application/pdf"
                      onChange={(e) => setDadosEditados({ ...dadosEditados, topico_rapido: e.target.files[0] })}
                    />
                    {servico.topico_rapido && (
                      <a href={servico.topico_rapido} target="_blank" rel="noreferrer">📎</a>
                    )}
                  </>
                ) : (
                  servico.topico_rapido ? (
                    <a href={servico.topico_rapido} target="_blank" rel="noreferrer">📎</a>
                  ) : "-"
                )}
              </td>

              {/* Ações */}
              <td className="acoes">
                {(perfilUsuario === "admin" || perfilUsuario === "coordenador") ? (
                  editandoId === servico.id ? (
                    <>
                      <button onClick={() => salvar(servico.id)}><Check size={16} /></button>
                      <button onClick={cancelar}><X size={16} /></button>
                    </>
                  ) : (
                    <>
                      <button onClick={() => editar(servico)}><Pencil size={16} /></button>
                      <button onClick={() => excluir(servico.id)}><Trash2 size={16} /></button>
                    </>
                  )
                ) : (
                  <span>-</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
